package cn.mop.api;
import cn.mop.domain.*;
import cn.mop.domain.inspection.*;
import cn.mop.domain.inspection.InspectionQuarterlyReportRepository.*;
import cn.mop.persistence.*;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.node.*;
import org.junit.jupiter.api.*;
import org.mockito.ArgumentCaptor;
import org.springframework.mock.web.MockHttpServletRequest;
import java.nio.charset.StandardCharsets;
import java.time.Instant;
import java.util.*;
import java.util.function.Supplier;
import static cn.mop.api.InspectionWorksheetControllerTest.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
/** Input/projection unit evidence only; real HTTP/PG checks are separate. */
class InspectionQuarterlyReportControllerTest {
    static final String COLLECTION="78000000-0000-4000-8000-000000000009";
    PlatformRepository platform;InspectionQuarterlyReportRepository repository;InspectionQuarterlyReportController controller;final ObjectMapper mapper=new ObjectMapper();Summary summary;String document;
    @BeforeEach void setup(){
        platform=mock(PlatformRepository.class);repository=mock(InspectionQuarterlyReportRepository.class);controller=new InspectionQuarterlyReportController(platform,repository);
        when(platform.membership(ACTOR,TENANT)).thenReturn(Optional.of(new Membership(ACTOR,TENANT,"padmin",7,true)));
        when(platform.idempotentAuthorized(any(),any(),any(),any(),any(),anyLong(),any(),any())).thenAnswer(call->{((Runnable)call.getArgument(6)).run();return ((Supplier<?>)call.getArgument(7)).get();});
        var manifest=new InspectionSourceManifest(UUID.fromString(TENANT),List.of());var report=InspectionQuarterlyReport.generate(UUID.fromString(TENANT),manifest,new InspectionQuarterlyReport.Period(2026,4),InspectionQuarterlyReport.Configuration.pending(),InspectionQuarterlyReport.Completeness.COMPLETE_EXPLICIT_SELECTION);
        byte[] bytes=InspectionQuarterlyReportDocumentCodec.encode(COLLECTION,report);document=new String(bytes,StandardCharsets.UTF_8);
        summary=new Summary(ID,TENANT,ACTOR,Instant.parse("2026-10-19T00:00:00Z"),1,"合成季度草稿",COLLECTION,InspectionSourceDocumentCodec.hash(InspectionSourceDocumentCodec.encode(manifest)),manifest.fingerprint(),2026,4,report.fingerprint(),InspectionSourceDocumentCodec.hash(bytes));
        when(repository.create(any(),anyLong(),any())).thenReturn(summary);when(repository.get(any(),eq(ID))).thenReturn(new Stored(summary,document));when(repository.list(any(),anyInt(),any(),any())).thenReturn(List.of(summary));
    }
    Map<?,?> data(Object v){return (Map<?,?>)((Map<?,?>)v).get("data");}
    Access access(){return new Access(ACTOR,TENANT,7,"quarterly-test");}
    MockHttpServletRequest request(String method){var r=new MockHttpServletRequest(method,"/api/v1/inspection-quarterly-reports");r.setUserPrincipal(()->ACTOR);r.getSession().setAttribute("mop.tenant_id",TENANT);r.setAttribute("mop.trace_id","quarterly-test");r.addHeader("Idempotency-Key","quarterly-test");return r;}
    ObjectNode input(){var n=mapper.createObjectNode().put("expected_version",0).put("label",summary.label()).put("source_collection_id",COLLECTION).put("expected_source_document_sha256",summary.sourceDocumentSha256()).put("expected_source_manifest_sha256",summary.sourceManifestSha256()).put("year",2026).put("quarter",4);var c=n.putObject("configuration");for(String k:List.of("revision","time_zone","duplicate_rule","archived_rule","metric_version","report_template_version"))c.putNull(k);return n;}
    @Test void createUsesExactSourcePendingConfigurationAndReauthorizes(){var response=data(controller.write(input(),request("POST")));assertEquals("DRAFT",response.get("generation_status"));assertEquals(false,response.get("report_published"));assertNull(response.get("tenant_asset_population"));verify(repository).authorizeWrite(access());var capture=ArgumentCaptor.forClass(Creation.class);verify(repository).create(eq(access()),eq(0L),capture.capture());assertEquals(COLLECTION,capture.getValue().sourceCollectionId());assertEquals(InspectionQuarterlyReport.Configuration.pending(),capture.getValue().configuration());}
    @Test void detailContainsVerifiedFrozenDocumentWithoutSourceRecapture(){var response=data(controller.get(ID,request("GET")));assertEquals("FROZEN_INPUT_OUTPUT",response.get("projection"));assertEquals("VERIFIED_SERVER_SIDE",response.get("document_integrity"));assertEquals("REQUEST_DRAFT_NOT_APPROVED",((JsonNode)response.get("frozen_document")).path("configuration_source").asText());verify(repository).get(access(),ID);verify(repository,never()).create(any(),anyLong(),any());}
    @Test void listIsMetadataOnlyAndUsesBoundedLookahead(){var response=data(controller.list(request("GET")));assertEquals(20,response.get("page_size_limit"));verify(repository).list(access(),16,null,null);verify(repository,never()).get(any(),any());assertFalse(((Map<?,?>)((List<?>)response.get("items")).get(0)).containsKey("frozen_document"));}
    @Test void paginationCursorIsPairedAndStable(){when(repository.list(any(),anyInt(),any(),any())).thenReturn(Collections.nCopies(16,summary));var response=data(controller.list(request("GET")));assertEquals(true,response.get("has_more"));assertEquals(ID,response.get("next_before_id"));var r=request("GET");r.addParameter("page_size","10");r.addParameter("before_recorded_at",summary.recordedAt().toString());r.addParameter("before_id",ID);when(repository.list(eq(access()),eq(11),any(),any())).thenReturn(List.of(summary));controller.list(r);verify(repository).list(access(),11,summary.recordedAt(),ID);}
    @Test void rejectsClientAggregatesAndMissingConfigurationKeys(){for(String key:List.of("tenant_id","summary","sources","report_published","report_sha256")){var n=input().put(key,"forged");assertEquals(400,assertThrows(DomainException.class,()->controller.write(n,request("POST"))).status);}var n=input();((ObjectNode)n.get("configuration")).remove("time_zone");assertEquals(400,assertThrows(DomainException.class,()->controller.write(n,request("POST"))).status);verifyNoInteractions(repository);}
    @Test void rejectsNonintegerPeriodInvalidEnumsAndInvalidZone(){for(var n:List.of(input().put("year",2026.0),input().put("quarter",5),input().put("expected_version",1))){assertEquals(400,assertThrows(DomainException.class,()->controller.write(n,request("POST"))).status);}for(var pair:Map.of("time_zone","Mars/Unknown","duplicate_rule","GUESS_LATEST","archived_rule","DEFAULT").entrySet()){var n=input();((ObjectNode)n.get("configuration")).put(pair.getKey(),pair.getValue());assertEquals(400,assertThrows(DomainException.class,()->controller.write(n,request("POST"))).status);}verifyNoInteractions(repository);}
    @Test void configuredValuesAreExplicitAndPreserved(){var n=input();var c=(ObjectNode)n.get("configuration");c.put("revision","SYNTHETIC").put("time_zone","UTC").put("duplicate_rule","REQUIRE_SINGLE_SOURCE").put("archived_rule","EXCLUDE").put("metric_version","test-v1").put("report_template_version","test-v1");controller.write(n,request("POST"));var capture=ArgumentCaptor.forClass(Creation.class);verify(repository).create(any(),eq(0L),capture.capture());assertEquals("UTC",capture.getValue().configuration().timeZone());assertEquals(InspectionQuarterlyReport.ArchivedRule.EXCLUDE,capture.getValue().configuration().archivedRule());}
    @Test void unauthorizedAndMissingSessionFailBeforeRepository(){for(String role:List.of("viewer","msp","tadmin")){when(platform.membership(ACTOR,TENANT)).thenReturn(Optional.of(new Membership(ACTOR,TENANT,role,7,true)));assertEquals(403,assertThrows(DomainException.class,()->controller.write(input(),request("POST"))).status);assertEquals(403,assertThrows(DomainException.class,()->controller.list(request("GET"))).status);}assertEquals(401,assertThrows(DomainException.class,()->controller.list(new MockHttpServletRequest())).status);verifyNoInteractions(repository);}
    @Test void missingIdempotencyKeyPreventsMutation(){var r=request("POST");r.removeHeader("Idempotency-Key");assertEquals(400,assertThrows(DomainException.class,()->controller.write(input(),r)).status);verifyNoInteractions(repository);}
    @Test void inputHashIncludesConfigurationAndIgnoresObjectKeyOrder()throws Exception{var a=input();var b=(ObjectNode)mapper.readTree(a.toString());var reordered=mapper.createObjectNode();var keys=new ArrayList<String>();b.fieldNames().forEachRemaining(keys::add);Collections.reverse(keys);keys.forEach(k->reordered.set(k,b.get(k)));var changed=input();((ObjectNode)changed.get("configuration")).put("revision","OTHER");controller.write(a,request("POST"));controller.write(reordered,request("POST"));controller.write(changed,request("POST"));var capture=ArgumentCaptor.forClass(String.class);verify(platform,times(3)).idempotentAuthorized(any(),any(),any(),any(),capture.capture(),anyLong(),any(),any());assertEquals(capture.getAllValues().get(0),capture.getAllValues().get(1));assertNotEquals(capture.getAllValues().get(0),capture.getAllValues().get(2));}
    @Test void requestBodyRejectsDuplicatesTrailingDataAndOversize(){for(String raw:List.of("null","{\"year\":1,\"year\":2}","{} {}","[[[[[{}]]]]]")){var r=request("POST");r.setContent(raw.getBytes(StandardCharsets.UTF_8));assertThrows(DomainException.class,()->controller.create(r));}var r=request("POST");r.setContent(new byte[InspectionQuarterlyReportController.MAX_BODY_BYTES+1]);assertEquals(413,assertThrows(DomainException.class,()->controller.create(r)).status);verifyNoInteractions(repository);}
    @Test void boundedValidJsonBodyCreatesDraft(){var r=request("POST");r.setContent(input().toString().getBytes(StandardCharsets.UTF_8));controller.create(r);verify(repository).create(eq(access()),eq(0L),any());}
    @Test void queriesRejectUnknownDuplicateAndUnpairedValues(){for(String name:List.of("tenant_id","year","unexpected")){var r=request("GET");r.addParameter(name,"x");assertThrows(DomainException.class,()->controller.list(r));}var r=request("GET");r.addParameter("before_id",ID);assertThrows(DomainException.class,()->controller.list(r));var twice=request("GET");twice.addParameter("page_size","10","15");assertThrows(DomainException.class,()->controller.list(twice));verifyNoInteractions(repository);}
    @Test void corruptedFrozenDocumentAndWrongScopeFailClosed(){when(repository.get(any(),any())).thenReturn(new Stored(summary,document.replace("DRAFT","PUBLISHED")));assertEquals(503,assertThrows(DomainException.class,()->controller.get(ID,request("GET"))).status);var foreign=new Summary(ID,ASSET,ACTOR,summary.recordedAt(),1,summary.label(),COLLECTION,summary.sourceDocumentSha256(),summary.sourceManifestSha256(),2026,4,summary.reportSha256(),summary.documentSha256());when(repository.get(any(),any())).thenReturn(new Stored(foreign,document));assertEquals(503,assertThrows(DomainException.class,()->controller.get(ID,request("GET"))).status);}
    @Test void sourceConflictAndUnavailableDoNotFallback(){for(int code:List.of(403,404,409,503)){doThrow(new DomainException(code,"SYNTHETIC","test")).when(repository).create(any(),anyLong(),any());assertEquals(code,assertThrows(DomainException.class,()->controller.write(input(),request("POST"))).status);}verify(repository,never()).get(any(),any());}
    @Test void selectedDetailIncludesItemsFindingsAndProducesSyntheticCrossLanguageFixtures()throws Exception{
        var directory=java.nio.file.Path.of("target/quarterly-report-fixtures");java.nio.file.Files.createDirectories(directory);
        java.nio.file.Files.writeString(directory.resolve("pending.json"),mapper.writeValueAsString(controller.get(ID,request("GET"))),StandardCharsets.UTF_8);
        var f=new InspectionWorksheetControllerTest();var content=new InspectionWorksheetRepository.Content(Map.of("firmware",new InspectionWorksheet.Observation(InspectionWorksheet.Result.ATTENTION,"合成😀原文",List.of())),Instant.parse("2026-10-04T08:00:00Z"));
        var source=InspectionSourceSnapshot.fromEntry(f.row(1,"CREATE",false,content,f.definition()));var manifest=new InspectionSourceManifest(UUID.fromString(TENANT),List.of(source));
        var config=new InspectionQuarterlyReport.Configuration("SYNTHETIC_REQUEST","UTC",InspectionQuarterlyReport.DuplicateRule.REQUIRE_SINGLE_SOURCE,InspectionQuarterlyReport.ArchivedRule.INCLUDE,"SYNTHETIC_V1","SYNTHETIC_V1");
        var report=InspectionQuarterlyReport.generate(UUID.fromString(TENANT),manifest,new InspectionQuarterlyReport.Period(2026,4),config,InspectionQuarterlyReport.Completeness.COMPLETE_EXPLICIT_SELECTION);byte[] bytes=InspectionQuarterlyReportDocumentCodec.encode(COLLECTION,report);
        var selected=new Summary(ID,TENANT,ACTOR,summary.recordedAt(),1,summary.label(),COLLECTION,InspectionSourceDocumentCodec.hash(InspectionSourceDocumentCodec.encode(manifest)),manifest.fingerprint(),2026,4,report.fingerprint(),InspectionSourceDocumentCodec.hash(bytes));
        when(repository.get(any(),any())).thenReturn(new Stored(selected,new String(bytes,StandardCharsets.UTF_8)));var result=controller.get(ID,request("GET"));var doc=(JsonNode)data(result).get("frozen_document");assertEquals(1,doc.path("output").path("findings").size());assertEquals(2,doc.path("output").path("rows").get(0).path("items").size());
        java.nio.file.Files.writeString(directory.resolve("selected.json"),mapper.writeValueAsString(result),StandardCharsets.UTF_8);
    }

}
